/* =================================== */
/* 语音气泡 */
/* =================================== */
:root{
  --voice-bubble-width:80px;
  --voice-fake-time:"13\"";
  --voice-icon-size:19px;
  --voice-text-size:12px;
  --voice-me-icon-x:5px;
  --voice-me-icon-y:0px;
  --voice-me-text-x:6px;
  --voice-me-text-y:0px;
  --voice-them-icon-x:-4px;
  --voice-them-icon-y:0px;
  --voice-them-text-x:-8px;
  --voice-them-text-y:0px;
  --voice-dl-offset:-35px;
}
.bubble-me-custom:has(.voice-msg),
.bubble-them-custom:has(.voice-msg){
  background:transparent!important;
  box-shadow:none!important;
  border:none!important;
  padding:0!important;
}
.bubble-me-custom:has(.voice-msg)::before,
.bubble-them-custom:has(.voice-msg)::before{display:none!important;}
.voice-msg{
  display:flex!important;
  flex-direction:column!important;
  width:fit-content!important;
  max-width:100%!important;
  min-width:0!important;
  padding:0!important;
  margin:0!important;
  position:relative!important;
  overflow:visible!important;
}
.voice-msg-me{align-items:flex-end!important;}
.voice-msg-them{align-items:flex-start!important;}
.voice-controls-row{
  width:var(--voice-bubble-width)!important;
  height:36px!important;
  border-radius:var(--wechat-bubble-radius)!important;
  position:relative!important;
  display:flex!important;
  align-items:center!important;
  padding:0!important;
  margin:0!important;
}
.voice-msg-me .voice-controls-row{background-color:var(--bubble-me-bg)!important;}
.voice-msg-them .voice-controls-row{background-color:var(--bubble-them-bg)!important;}
.voice-msg-me .voice-controls-row::before{
  content:""!important;
  display:block!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  right:var(--bubble-me-tail-right)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-me-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
}
.voice-msg-them .voice-controls-row::before{
  content:""!important;
  display:block!important;
  position:absolute!important;
  top:var(--bubble-tail-top)!important;
  left:var(--bubble-them-tail-left)!important;
  width:var(--bubble-tail-width)!important;
  height:var(--bubble-tail-height)!important;
  background-color:var(--bubble-them-bg)!important;
  pointer-events:none!important;
  border-radius: 2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
}
.voice-waveform,.voice-duration{display:none!important;}
.voice-play-btn{
  width:100%!important;
  height:100%!important;
  display:flex!important;
  align-items:center!important;
  background:transparent!important;
  border:none!important;
  padding:0 12px!important;
  box-sizing:border-box!important;
  position:relative!important;
}
.voice-msg-me .voice-play-btn{justify-content:flex-end!important;}
.voice-msg-them .voice-play-btn{justify-content:flex-start!important;}
.voice-msg-me .voice-play-btn::before{
  content:var(--voice-fake-time);
  font-size:var(--voice-text-size)!important;
  color:var(--bubble-me-color)!important;
  margin-right:6px!important;
  transform:translate(var(--voice-me-text-x),var(--voice-me-text-y))!important;
}
.voice-msg-me .voice-play-btn::after{
  content:"";
  display:block;
  width:var(--voice-icon-size)!important;
  height:var(--voice-icon-size)!important;
