.bubble-me-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before{content:var(--call-text-me-cancel)!important;}
.bubble-them-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before{content:var(--call-text-them-reject)!important;}
.msg-videocall-card.connected > div:nth-child(2) > div:first-child::before{content:var(--call-text-connected)!important;}
.msg-videocall-card > div:nth-child(2) > div:nth-child(2),
.msg-videocall-card > div:nth-child(2) > div:nth-child(2) *{
  display:none!important;
